def apply_batches(stock, batches):
    result = dict(stock)
    applied_ids = set()
    statuses = []

    for batch in batches:
        batch_id = batch["id"]
        if batch_id in applied_ids:
            statuses.append("duplicate")
            continue

        deltas = {}
        for sku, delta in batch["lines"]:
            deltas[sku] = deltas.get(sku, 0) + delta

        balances = {sku: result.get(sku, 0) + delta for sku, delta in deltas.items()}
        if any(balance < 0 for balance in balances.values()):
            statuses.append("insufficient")
            continue

        for sku, balance in balances.items():
            if balance == 0:
                result.pop(sku, None)
            else:
                result[sku] = balance

        applied_ids.add(batch_id)
        statuses.append("applied")

    return {"stock": result, "statuses": statuses}

